<?php session_start(); require '../config.php'; require_admin(); $no=$_GET['no']??''; $st=db()->prepare("SELECT * FROM applications WHERE application_no=?");$st->execute([$no]);$a=$st->fetch();if(!$a){http_response_code(404);exit('Application not found.');} if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$status=$_POST['status']??'Pending';if(!in_array($status,['Pending','Under Review','Accepted','Rejected'],true))$status='Pending';$note=trim($_POST['admin_note']??'');$q=db()->prepare("UPDATE applications SET status=?,admin_note=? WHERE application_no=?");$q->execute([$status,$note,$no]);redirect('application.php?no='.urlencode($no));} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($a['application_no'])?></title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="admin-body"><header class="admin-head"><div><img src="../assets/images/school-logo.png"><strong>ME’RAJ ADMIN PORTAL</strong></div><nav><a href="dashboard.php">Dashboard</a><a href="applications.php">Applications</a><a href="media.php">Media</a><a href="logout.php">Logout</a></nav></header><main class="admin-main"><div class="container"><div class="section-head"><h1><?=e($a['application_no'])?></h1><a class="btn btn-small" href="javascript:window.print()">Print</a></div><div class="detail-grid"><div class="card"><h2>Student Information</h2><?php if($a['passport_path']): ?><img class="passport" src="../<?=e($a['passport_path'])?>"><?php endif; ?><p><b>Name:</b> <?=e($a['full_name'])?></p><p><b>Date of Birth:</b> <?=e($a['dob'])?></p><p><b>Gender:</b> <?=e($a['gender'])?></p><p><b>Nationality:</b> <?=e($a['nationality'])?></p><p><b>State/LGA:</b> <?=e($a['state_of_origin'])?> / <?=e($a['lga'])?></p><p><b>Address:</b> <?=nl2br(e($a['address']))?></p><h3>Academic</h3><p><b>Section/Class:</b> <?=e($a['applying_section'])?> / <?=e($a['class_applied'])?></p><p><b>Previous School:</b> <?=e($a['previous_school'])?></p><p><b>Previous Class:</b> <?=e($a['previous_class'])?></p><h3>Islamic & Arabic</h3><p><b>Qur’an:</b> <?=e($a['quran_level'])?></p><p><b>Arabic:</b> <?=e($a['arabic_level'])?></p><p><b>Additional:</b> <?=nl2br(e($a['additional_info']))?></p><?php if($a['document_path']): ?><p><a href="../<?=e($a['document_path'])?>" target="_blank">View supporting document</a></p><?php endif; ?></div><div><div class="card"><h2>Parent / Guardian</h2><p><b>Name:</b> <?=e($a['parent_name'])?></p><p><b>Phone:</b> <?=e($a['parent_phone'])?></p><p><b>Email:</b> <?=e($a['parent_email'])?></p><p><b>Address:</b> <?=nl2br(e($a['parent_address']))?></p></div><form class="card" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><h2>Application Decision</h2><label>Status<select name="status"><?php foreach(['Pending','Under Review','Accepted','Rejected'] as $s): ?><option <?=$a['status']===$s?'selected':''?>><?=$s?></option><?php endforeach; ?></select></label><label>Admin Note<textarea name="admin_note"><?=e($a['admin_note'])?></textarea></label><button class="btn">Save Decision</button></form></div></div></div></main></body></html>